python3 -c '
def parse_fasta(path):
    res = []
    with open(path) as f:
        content = f.read().strip()
    for block in content.split(">"):
        if not block: continue
        lines = block.splitlines()
        res.append((lines[0], "".join(lines[1:])))
    return res

asvs = parse_fasta("/tmp/candidate_asvs.fa")
print(f"Loaded {len(asvs)} ASVs")

def dist(s1, s2):
    if len(s1) != len(s2):
        return 999
    return sum(a != b for a, b in zip(s1, s2))

s11_reads = []
with open("/tmp/processed/S11_trimmed.fq") as f:
    for i, l in enumerate(f):
        if i % 4 == 1: s11_reads.append(l.strip())

from collections import Counter
dist_counts = Counter()
for r in s11_reads:
    min_d = min(dist(r, a[1]) for a in asvs)
    dist_counts[min_d] += 1

for d in sorted(dist_counts.keys()):
    print(f"Dist {d}: {dist_counts[d]} reads ({dist_counts[d]/len(s11_reads)*100:.2f}%)")
'

